import json,threading
from functools import partial
from playwright.sync_api import sync_playwright,expect
from voyage_browser import ROOT,Quiet,Server

def main():
 teams=[
  {'id':'unfinished','name':'Équipe à finir','members':[{'character':'10000005'},{'character':'a'},{},{}],'rotation':[{'type':'skill','name':'Action A','code':'E'},{'type':'burst','name':'Action B','code':'Q'}]},
  {'id':'complete','name':'Équipe favorite','favorite':True,'members':[{'character':'10000005'},{'character':'b'},{'character':'c'},{'character':'d'}],'rotation':[{'type':'burst'}]},
 ]
 server=Server(('127.0.0.1',0),partial(Quiet,directory=str(ROOT)));threading.Thread(target=server.serve_forever,daemon=True).start();base=f'http://127.0.0.1:{server.server_port}'
 try:
  with sync_playwright() as p:
   browser=p.chromium.launch();page=browser.new_page(service_workers='block');page.set_default_timeout(180000);page.set_default_navigation_timeout(180000);errors=[];page.on('pageerror',lambda e:errors.append(f'{e} {e.stack}'))
   page.add_init_script('localStorage.setItem("astralis:active-game","gi");localStorage.setItem("astralis:teams:gi",'+json.dumps(json.dumps(teams,ensure_ascii=False))+');localStorage.setItem("astralis:gi:assistant-profile","{\"enabled\":false}")')
   page.add_init_script("Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{window.__astralisClipboard=text}}})")
   page.route('**/*',lambda r:r.continue_() if r.request.url.startswith(base) else r.abort())
   page.goto(base,wait_until='domcontentloaded');page.wait_for_selector('#astralis-launch-screen',state='detached');page.locator('[data-game=gi]').first.click(no_wait_after=True);page.evaluate('teams=>localStorage.setItem("astralis:teams:gi",JSON.stringify(teams))',teams);errors.clear();page.locator('[data-nav=teams]').first.click(no_wait_after=True)
   expect(page.locator('.team-role-summary').first).to_contain_text('0/2 rôles renseignés')
   page.locator('.team-sheet-head [data-edit-team="unfinished"]').click();role=page.locator('.team-role-select select').first;expect(role.locator('option')).to_have_count(6);role.select_option('main-dps');page.locator('[data-save-team]').click()
   expect(page.locator('.team-role-summary').first).to_contain_text('1/2 rôles renseignés');expect(page.locator('.team-role-summary').first).to_contain_text('DPS principal ×1')
   expect(page.locator('.team-role-advice').first).to_contain_text('1 rôle à préciser')
   assert page.evaluate("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').members[0].role")=='main-dps'
   portrait=page.evaluate_handle("""()=>{const roster=document.createElement('div');roster.className='team-roster qa-team-roster';const art=document.createElement('div');art.className='unit-art';roster.append(art);document.body.append(roster);return art}""")
   page.set_viewport_size({'width':1920,'height':1080});wide_height=portrait.evaluate('el=>el.getBoundingClientRect().height');assert 260<=wide_height<=331,f'1920 portrait height: {wide_height}'
   page.set_viewport_size({'width':390,'height':844});mobile_height=portrait.evaluate('el=>el.getBoundingClientRect().height');assert 190<=mobile_height<=261,f'mobile portrait height: {mobile_height}'
   page.set_viewport_size({'width':1280,'height':800})
   page.evaluate("""()=>{const host=document.createElement('div');host.className='teams-stack';host.innerHTML='<article class="team-sheet"><header class="team-sheet-head"><div><span>ÉQUIPE</span><h3>Équipe QA</h3><p>4 étapes dans la rotation</p><div class="team-roster-meter"><span></span><small>4 / 4</small></div></div><div class="team-sheet-actions"><button class="quiet-btn">Modifier</button><button class="quiet-btn">Copier</button></div></header><div class="team-compact-roster">'+Array.from({length:4},(_,i)=>'<button class="team-compact-member"><img class="team-compact-avatar"/><b>Personnage '+i+'</b></button>').join('')+'</div><button class="team-details-toggle">Détails</button></article>';document.body.append(host)}""")
   team_card=page.locator('body > .teams-stack .team-sheet')
   normal_height=team_card.evaluate('el=>el.getBoundingClientRect().height')
   page.evaluate("document.documentElement.dataset.density='compact'")
   compact_height=team_card.evaluate('el=>el.getBoundingClientRect().height')
   assert compact_height < normal_height-24, f'la densité compacte ne réduit pas la fiche: {normal_height} -> {compact_height}'
   page.evaluate("document.documentElement.dataset.density='comfortable';document.querySelector('body > .teams-stack')?.remove()")
   page.locator('[data-team-compare-toggle="unfinished"]').click();page.locator('[data-team-compare-toggle="complete"]').click();panel=page.locator('.team-comparison-panel');expect(panel).to_be_visible();expect(panel).to_contain_text('Aether');expect(panel).to_contain_text('2/4');expect(panel).to_contain_text('2 actions')
   page.set_viewport_size({'width':390,'height':844});assert panel.evaluate('el=>el.scrollWidth<=el.clientWidth+1'),'comparison overflows mobile';panel.locator('[data-team-compare-toggle="unfinished"]').click();expect(page.locator('.team-comparison-panel')).to_have_count(0)
   page.locator('[data-team-compare-clear]').click();expect(page.locator('[data-team-compare-toggle][aria-pressed="true"]')).to_have_count(0);page.set_viewport_size({'width':1280,'height':800})
   filters=page.locator('.team-library-filters');expect(filters).to_be_visible();expect(filters.locator('button').nth(0)).to_contain_text('2');expect(page.locator('.team-sheet')).to_have_count(2);bulk=page.locator('[data-team-details-all]');bulk.click();expect(bulk).to_have_attribute('aria-expanded','true');expect(page.locator('[data-team-details]')).to_have_count(2);expect(page.locator('[data-team-details]:visible')).to_have_count(2);assert set(page.evaluate("JSON.parse(localStorage.getItem('astralis:gi:team-expanded-details'))"))=={'unfinished','complete'}
   page.locator('[data-team-library-sort]').select_option('name');expect(page.locator('[data-team-details]:visible')).to_have_count(2);expect(page.locator('[data-team-details-toggle][aria-expanded="true"]')).to_have_count(2);page.locator('[data-team-details-toggle="unfinished"]').click();expect(page.locator('[data-team-details]:visible')).to_have_count(1);expect(bulk).to_have_attribute('aria-expanded','false');assert page.evaluate("JSON.parse(localStorage.getItem('astralis:gi:team-expanded-details'))")==['complete'];page.locator('[data-team-library-sort]').select_option('saved');expect(page.locator('[data-team-details]:visible')).to_have_count(1);page.locator('[data-team-details-toggle="unfinished"]').click();expect(page.locator('[data-team-details]:visible')).to_have_count(2)
   page.locator('[data-move-step="unfinished:1:-1"]').click();page.wait_for_function("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation[0].name==='Action B'");assert page.evaluate("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation.map(x=>x.name)")==['Action B','Action A']
   page.locator('[data-rotation-drag="unfinished"][data-rotation-index="0"]').drag_to(page.locator('[data-rotation-drag="unfinished"][data-rotation-index="1"]'));page.wait_for_function("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation[0].name==='Action A'");assert page.evaluate("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation.map(x=>x.name)")==['Action A','Action B']
   page.locator('[data-rotation-variant-name="unfinished"]').fill('Ouverture');page.locator('[data-save-rotation-variant="unfinished"]').click();variant=page.locator('[data-rotation-variant="unfinished"]');variant_id=variant.input_value();assert variant_id and page.evaluate("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotationVariants.length")==1
   page.locator('[data-move-step="unfinished:0:1"]').click();page.wait_for_function("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation[0].name==='Action B'");variant.select_option('');assert page.evaluate("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation.map(x=>x.name)")==['Action A','Action B'];variant=page.locator('[data-rotation-variant="unfinished"]');variant.select_option(variant_id);assert page.evaluate("JSON.parse(localStorage.getItem('astralis:teams:gi')).find(x=>x.id==='unfinished').rotation.map(x=>x.name)")==['Action B','Action A']
   page.evaluate("""()=>{document.querySelectorAll("[data-team-details]").forEach(x=>x.hidden=true);document.querySelectorAll("[data-team-details-toggle]").forEach(x=>x.setAttribute("aria-expanded","false"))}""");expect(page.locator("[data-team-details]:visible")).to_have_count(0);portrait=page.locator('[data-team-character-detail=\"10000005\"]').first;expect(portrait).to_be_visible();expect(portrait).to_have_attribute('aria-label','Ouvrir la fiche de Aether');portrait.click();expect(page.get_by_role('dialog',name='Aether')).to_be_visible();page.keyboard.press('Escape');page.locator('[data-team-copy-rotation]').first.click();page.wait_for_function("typeof window.__astralisClipboard==='string'");assert 'Équipe à finir' in page.evaluate('window.__astralisClipboard') and 'Rotation :' in page.evaluate('window.__astralisClipboard');search=page.locator('[data-team-library-search]');search.fill('favorite');expect(page.locator('.team-search-record:visible .team-sheet')).to_have_count(1);expect(page.locator('.team-search-record:visible .team-sheet')).to_contain_text('Équipe favorite');search.fill('aucun resultat');expect(page.locator('.team-search-empty')).to_be_visible();page.locator('[data-team-library-search-clear]').click();expect(page.locator('.team-sheet')).to_have_count(2)
   filters.locator('[data-team-library-filter="incomplete"]').click();expect(page.locator('.team-sheet')).to_have_count(1);expect(page.locator('.team-sheet')).to_contain_text('Équipe à finir')
   filters.locator('[data-team-library-filter="favorites"]').click();expect(page.locator('.team-sheet')).to_have_count(1);expect(page.locator('.team-sheet')).to_contain_text('Équipe favorite')
   page.locator('#team-focus-select').select_option('unfinished');filters=page.locator('.team-library-filters');filters.locator('[data-team-library-filter="favorites"]').click();expect(page.locator('.team-filter-empty')).to_be_visible();page.locator('.team-filter-empty [data-team-library-filter="all"]').click();expect(page.locator('.team-sheet')).to_have_count(1)
   page.evaluate("""()=>{const teams=JSON.parse(localStorage.getItem('astralis:teams:gi'));const copy=structuredClone(teams.find(x=>x.id==='complete'));copy.id='complete-copy';copy.name='Même équipe, autre ordre';copy.members.reverse();teams.push(copy);localStorage.setItem('astralis:teams:gi',JSON.stringify(teams));localStorage.setItem('astralis:gi:team-focus','all')}""")
   page.locator('[data-nav="dashboard"]').first.click();page.locator('[data-nav="teams"]').first.click();filters=page.locator('.team-library-filters');filters.locator('[data-team-library-filter="duplicates"]').click();expect(page.locator('.team-sheet')).to_have_count(2);expect(page.locator('.team-duplicate-hint')).to_have_count(2);expect(page.locator('[data-team-library-count]')).to_contain_text('2 équipes')
   assert not errors,errors;browser.close()
  print('OK : recherche, filtres, ouverture groupée des équipes, copie de rotation et état vide récupérable.')
 finally:server.shutdown();server.server_close()
if __name__=='__main__':main()
